const assert = require('node:assert/strict');
const { DocumentRepository } = require('../.build/repository');
const { DocumentService } = require('../.build/service');

const seed = () => [
  { id: 'own', tenant: 'a', owner: 'ed', deleted: false, archived: false },
  { id: 'other', tenant: 'a', owner: 'zed', deleted: false, archived: false },
  { id: 'gone', tenant: 'a', owner: 'ed', deleted: true, archived: false },
  { id: 'foreign', tenant: 'b', owner: 'ed', deleted: false, archived: false },
  { id: 'done-own', tenant: 'a', owner: 'ed', deleted: false, archived: true },
  { id: 'done-other', tenant: 'a', owner: 'zed', deleted: false, archived: true },
];

const setup = () => {
  const repo = new DocumentRepository(seed());
  return { repo, service: new DocumentService(repo) };
};

const admin = { tenant: 'a', user: 'adm', role: 'admin' };
const foreignAdmin = { tenant: 'b', user: 'badm', role: 'admin' };
const editor = { tenant: 'a', user: 'ed', role: 'editor' };
const otherEditor = { tenant: 'a', user: 'ben', role: 'editor' };
const viewer = { tenant: 'a', user: 'vw', role: 'viewer' };
const ownerViewer = { tenant: 'a', user: 'ed', role: 'viewer' };
const unknownRole = { tenant: 'a', user: 'ed', role: 'owner' };

const snap = (repo) => JSON.parse(JSON.stringify({ documents: repo.documents, audit: repo.audit }));

function expectFailure(service, repo, actor, id, message) {
  const before = snap(repo);
  assert.throws(() => service.archive(actor, id), { name: 'Error', message });
  assert.deepEqual(snap(repo), before);
}

function expectArchived(service, repo, actor, id) {
  const before = snap(repo);
  assert.equal(before.documents.find((d) => d.id === id).archived, false, 'precondition: not archived');
  service.archive(actor, id);
  const expected = structuredClone(before);
  expected.documents.find((d) => d.id === id).archived = true;
  expected.audit.push({ actor: actor.user, document: id });
  assert.deepEqual(snap(repo), expected);
}

function expectNoop(service, repo, actor, id) {
  const before = snap(repo);
  assert.equal(before.documents.find((d) => d.id === id).archived, true, 'precondition: archived');
  service.archive(actor, id);
  assert.deepEqual(snap(repo), before);
}

const tests = [];
const test = (name, fn) => tests.push({ name, fn });

// Not found: missing, deleted, and foreign-tenant documents, for every actor including admin.
test('admin: missing -> not found', () => {
  const { service, repo } = setup();
  expectFailure(service, repo, admin, 'missing', 'not found');
});
test('admin: deleted -> not found', () => {
  const { service, repo } = setup();
  expectFailure(service, repo, admin, 'gone', 'not found');
});
test('admin: foreign tenant -> not found', () => {
  const { service, repo } = setup();
  expectFailure(service, repo, admin, 'foreign', 'not found');
});
test('foreign-tenant admin: own-tenant document -> not found', () => {
  const { service, repo } = setup();
  expectFailure(service, repo, foreignAdmin, 'own', 'not found');
});
test('editor: foreign-tenant doc owned by same user name -> not found', () => {
  const { service, repo } = setup();
  expectFailure(service, repo, editor, 'foreign', 'not found');
});
test('editor: own but deleted -> not found', () => {
  const { service, repo } = setup();
  expectFailure(service, repo, editor, 'gone', 'not found');
});
test('viewer: foreign tenant -> not found, not forbidden', () => {
  const { service, repo } = setup();
  expectFailure(service, repo, viewer, 'foreign', 'not found');
});
test('viewer: missing -> not found', () => {
  const { service, repo } = setup();
  expectFailure(service, repo, viewer, 'missing', 'not found');
});

// Admin: any visible document.
test('admin archives a visible document owned by someone else', () => {
  const { service, repo } = setup();
  expectArchived(service, repo, admin, 'other');
  assert.deepEqual(repo.audit, [{ actor: 'adm', document: 'other' }]);
});
test('admin archives own visible document', () => {
  const { service, repo } = setup();
  expectArchived(service, repo, admin, 'own');
});

// Editor: only owned documents.
test('editor archives own visible document', () => {
  const { service, repo } = setup();
  expectArchived(service, repo, editor, 'own');
  assert.deepEqual(repo.audit, [{ actor: 'ed', document: 'own' }]);
});
test('editor: visible document owned by someone else -> forbidden', () => {
  const { service, repo } = setup();
  expectFailure(service, repo, editor, 'other', 'forbidden');
});
test('other editor: visible document owned by someone else -> forbidden', () => {
  const { service, repo } = setup();
  expectFailure(service, repo, otherEditor, 'own', 'forbidden');
});

// Viewer: never.
test('viewer: visible own-tenant document -> forbidden', () => {
  const { service, repo } = setup();
  expectFailure(service, repo, viewer, 'other', 'forbidden');
});
test('viewer who owns the document -> still forbidden', () => {
  const { service, repo } = setup();
  expectFailure(service, repo, ownerViewer, 'own', 'forbidden');
});
test('unrecognised role -> forbidden', () => {
  const { service, repo } = setup();
  expectFailure(service, repo, unknownRole, 'own', 'forbidden');
});

// Already-archived visible documents: permission is enforced first, then no-op.
test('admin repeat on already-archived visible document -> no-op', () => {
  const { service, repo } = setup();
  expectNoop(service, repo, admin, 'done-other');
  expectNoop(service, repo, admin, 'done-own');
  assert.deepEqual(repo.audit, []);
});
test('editor repeat on already-archived own document -> no-op', () => {
  const { service, repo } = setup();
  expectNoop(service, repo, editor, 'done-own');
  assert.deepEqual(repo.audit, []);
});
test('editor repeat on already-archived document owned by someone else -> forbidden', () => {
  const { service, repo } = setup();
  expectFailure(service, repo, editor, 'done-other', 'forbidden');
});
test('viewer repeat on already-archived visible document -> forbidden', () => {
  const { service, repo } = setup();
  expectFailure(service, repo, viewer, 'done-own', 'forbidden');
  expectFailure(service, repo, ownerViewer, 'done-own', 'forbidden');
});
test('already-archived but deleted document -> not found', () => {
  const { service, repo } = setup();
  repo.documents.push({ id: 'gone-done', tenant: 'a', owner: 'ed', deleted: true, archived: true });
  expectFailure(service, repo, admin, 'gone-done', 'not found');
});

// Repeated successful archive writes exactly one audit entry.
test('repeated successful archive appends one audit entry', () => {
  const { service, repo } = setup();
  service.archive(admin, 'other');
  service.archive(admin, 'other');
  service.archive(editor, 'own');
  service.archive(editor, 'own');
  assert.deepEqual(repo.audit, [
    { actor: 'adm', document: 'other' },
    { actor: 'ed', document: 'own' },
  ]);
  assert.equal(repo.documents.find((d) => d.id === 'other').archived, true);
  assert.equal(repo.documents.find((d) => d.id === 'own').archived, true);
});

// A mixed sequence: only successful calls leave a trace.
test('failed calls in a sequence leave no trace', () => {
  const { service, repo } = setup();
  const attempts = [
    [viewer, 'own'], [editor, 'other'], [admin, 'missing'], [editor, 'foreign'],
    [admin, 'other'], [viewer, 'other'], [editor, 'own'], [admin, 'gone'],
  ];
  for (const [actor, id] of attempts) {
    try { service.archive(actor, id); } catch (_) { /* expected for most */ }
  }
  assert.deepEqual(repo.audit, [
    { actor: 'adm', document: 'other' },
    { actor: 'ed', document: 'own' },
  ]);
  assert.deepEqual(
    repo.documents.map((d) => [d.id, d.archived]),
    [['own', true], ['other', true], ['gone', false], ['foreign', false], ['done-own', true], ['done-other', true]],
  );
});

let failed = 0;
for (const { name, fn } of tests) {
  try {
    fn();
    console.log(`ok   - ${name}`);
  } catch (err) {
    failed++;
    console.log(`FAIL - ${name}\n       ${err && err.message}`);
  }
}
console.log(`${tests.length - failed}/${tests.length} passed`);
if (failed) process.exitCode = 1;

